        pts=[c for c in range(W) if g[row][c]==2]
        if len(pts)<2: return
        for k in range(len(pts)-1):
            a,b=pts[k],pts[k+1]
            lo,hi=a+1,b-1; filled=[]
            while lo<=hi: filled.append(lo); lo+=1; hi-=1
            if not filled: continue
            arm_lo=sum(1 for x in range(a-lo,a) if g[row][x]==2)
            arm_hi=sum(1 for x in range(b+lo,W) if g[row][x]==2)
            if arm_lo==arm_hi:
                for j in filled: out[row][j]=1
    def vline(col):
        pts=[r for r in range(H) if g[r][col]==2]
        if len(pts)<2: return
        for k in range(len(pts)-1):
            a,b=pts[k],pts[k+1]
            lo,hi=a+1,b-1; filled=[]
            while lo<=hi: filled.append(lo); lo+=1; hi-=1
            if not filled: continue
            arm_lo=sum(1 for y in range(a-lo,a) if g[y][col]==2)
            arm_hi=sum(1 for y in range(b+lo,H) if g[y][col]==2)
            if arm_lo==arm_hi:
                for rr in filled: out[rr][col]=1
    for r in range(H): hline(r)
    for c in range(W): vline(c)
    return out
